-- ============================================================
-- Trava: contagem e somas medidas na planilha ao gerar este arquivo.
-- Se a carga divergir, a migration falha e nada e gravado.
-- ============================================================

do $$
declare
  v_qtd bigint;
  v_soma numeric;
begin
  select count(*) into v_qtd from public.stg_br364_lancamentos;
  if v_qtd <> 1647 then
    raise exception 'stg_br364_lancamentos: carregou % linhas, esperado 1647', v_qtd;
  end if;
  select coalesce(sum(valor::numeric), 0) into v_soma from public.stg_br364_lancamentos;
  if v_soma <> 21947586.67 then
    raise exception 'stg_br364_lancamentos.valor: somou %, esperado 21947586.67', v_soma;
  end if;
  select count(*) into v_qtd from public.stg_br364_pagamentos;
  if v_qtd <> 1773 then
    raise exception 'stg_br364_pagamentos: carregou % linhas, esperado 1773', v_qtd;
  end if;
  select coalesce(sum(valor_parcela::numeric), 0) into v_soma from public.stg_br364_pagamentos;
  if v_soma <> 19509415.79 then
    raise exception 'stg_br364_pagamentos.valor_parcela: somou %, esperado 19509415.79', v_soma;
  end if;
  select coalesce(sum(valor_em_aberto::numeric), 0) into v_soma from public.stg_br364_pagamentos;
  if v_soma <> 0 then
    raise exception 'stg_br364_pagamentos.valor_em_aberto: somou %, esperado 0', v_soma;
  end if;
  select coalesce(sum(valor_pago_parcela::numeric), 0) into v_soma from public.stg_br364_pagamentos;
  if v_soma <> 19509415.79 then
    raise exception 'stg_br364_pagamentos.valor_pago_parcela: somou %, esperado 19509415.79', v_soma;
  end if;
  select coalesce(sum(juros_multas::numeric), 0) into v_soma from public.stg_br364_pagamentos;
  if v_soma <> 0 then
    raise exception 'stg_br364_pagamentos.juros_multas: somou %, esperado 0', v_soma;
  end if;
  select coalesce(sum(descontos::numeric), 0) into v_soma from public.stg_br364_pagamentos;
  if v_soma <> 24615.23 then
    raise exception 'stg_br364_pagamentos.descontos: somou %, esperado 24615.23', v_soma;
  end if;
  select coalesce(sum(valor_total_pago::numeric), 0) into v_soma from public.stg_br364_pagamentos;
  if v_soma <> 19484800.56 then
    raise exception 'stg_br364_pagamentos.valor_total_pago: somou %, esperado 19484800.56', v_soma;
  end if;
end $$;
